  array('ID' => '222','post_author' => '1','post_date' => '2013-01-07 18:21:37','post_date_gmt' => '2013-01-07 18:21:37','post_content' => '<!-- begin types of images -->
<section>
<h2>Types of Images</h2>

[gc layout="4" separator="|"]
<h3>Simple Image</h3>
[img src="dining-and-living-cream" size="thumb" lightbox="false" title="Image Title"][/img]|
<h3>Image with Caption</h3>
[img src="living-large-windows" size="thumb" lightbox="false" title="Image Title" caption="Caption Text"][/img]|
<h3>Image with Lightbox</h3>
[img src="living-white" size="thumb" lightbox="true" title="Image Title"][/img]|
<h3>Image with Lightbox Gallery</h3>
[gallery slide="false" name="gallery-study" size="thumb" lightbox="true"][gallery_item src="study" title="Project Title"][gallery_item src="dining-white2" title="Project Title"][gallery_item src="living-brown" title="Project Title"][/gallery][/gc]
<div class="clear"></div>
</section>
<!-- end types of images -->

<hr>

<!-- begin aligned images -->
<section>

<h2>Aligned Images</h2>
<!-- begin left-aligned image -->
<h3>Left-Aligned Image</h3>
